<script setup lang="ts">
import { ref, computed, watch, onMounted, onBeforeUnmount, nextTick } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { conversationApi } from '@/api/conversation'
import { mediaApi, socialApi } from '@/api/social'
import { useAuthStore } from '@/stores/auth'
import { useConversationsStore } from '@/stores/conversations'
import ProtectedImage from '@/components/ProtectedImage.vue'
import ws from '@/websocket/stomp'
import type { Conversation, ConversationMessage, SendMessage } from '@/types/conversation'
import type { PublicUser } from '@/types/social'
const route=useRoute(),router=useRouter(),auth=useAuthStore(),store=useConversationsStore()
const current=ref<Conversation|null>(null),messages=ref<ConversationMessage[]>([]),draft=ref(''),loading=ref(false),error=ref(''),sending=ref(false),hasMore=ref(false),before=ref<number|null>(null),olderLoading=ref(false)
const scroller=ref<HTMLElement>(),fileInput=ref<HTMLInputElement>(),image=ref<{id:string;url:string}|null>(null),uploading=ref(false)
const groupOpen=ref(false),groupName=ref(''),joinCode=ref(''),groupBusy=ref(false),membersOpen=ref(false),members=ref<PublicUser[]>([]),friendChoices=ref<PublicUser[]>([]),inviteTarget=ref<number>(),inviteBusy=ref(false)
const emojis=['😀','😂','🥰','😎','🤔','😭','👍','🎉','🐺','🌙','❤️','👋']
let generation=0,requestSequence=0,off:(()=>void)|undefined,offStatus:(()=>void)|undefined,retry:SendMessage|null=null,inviteKey=''
const activeId=computed(()=>{const n=Number(route.params.id);return Number.isSafeInteger(n)&&n>0?n:null})
function msg(e:unknown){return e instanceof Error?e.message:'操作失败，请重试'}
function preview(c:Conversation){return !c.lastMessage?'还没有消息':c.lastMessage.contentType==='IMAGE'?'[图片]':c.lastMessage.contentType==='GROUP_INVITE'?'[群邀请]':c.lastMessage.contentType==='GAME_INVITE'?'[游戏邀请]':c.lastMessage.content}
function time(value:string){return new Date(value).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'})}
async function bottom(){await nextTick();scroller.value?.scrollTo({top:scroller.value.scrollHeight})}
async function markRead(){const id=activeId.value,last=messages.value.at(-1);if(!id||!last||document.hidden)return;try{await conversationApi.read(id,last.id);await store.refresh()}catch(e){error.value=msg(e)}}
async function loadLatest(clear=true){const id=activeId.value,run=++requestSequence,epoch=generation;if(!id){current.value=null;messages.value=[];return}loading.value=clear;error.value='';try{const [c,h]=await Promise.all([conversationApi.get(id),conversationApi.history(id)]);if(epoch!==generation||run!==requestSequence||id!==activeId.value)return;current.value=c;const newest=h.items.at(-1)?.id||0;messages.value=[...h.items,...messages.value.filter(m=>m.id>newest)].sort((a,b)=>a.id-b.id);hasMore.value=h.hasMore;before.value=h.nextBeforeId;await bottom();await markRead()}catch(e){if(epoch===generation&&run===requestSequence){error.value=msg(e);if(clear)current.value=null}}finally{if(epoch===generation&&run===requestSequence)loading.value=false}}
async function older(){const id=activeId.value,cursor=before.value,epoch=generation;if(!id||!cursor||olderLoading.value)return;olderLoading.value=true;const height=scroller.value?.scrollHeight||0;try{const h=await conversationApi.history(id,cursor);if(epoch!==generation||id!==activeId.value)return;const seen=new Set(messages.value.map(m=>m.id));messages.value=[...h.items.filter(m=>!seen.has(m.id)),...messages.value];before.value=h.nextBeforeId;hasMore.value=h.hasMore;await nextTick();scroller.value?.scrollTo({top:scroller.value.scrollHeight-height})}catch(e){if(epoch===generation)error.value=msg(e)}finally{if(epoch===generation)olderLoading.value=false}}
async function send(){const id=activeId.value;if(!id||sending.value||uploading.value||(!draft.value.trim()&&!image.value))return;if([...draft.value.trim()].length>2000){ElMessage.warning('消息最多2000字');return}const epoch=generation;const payload:SendMessage=image.value?{contentType:'IMAGE',mediaId:image.value.id,clientMessageId:''}:{contentType:'TEXT',content:draft.value.trim(),clientMessageId:''};const same=retry&&retry.contentType===payload.contentType&&retry.content===payload.content&&retry.mediaId===payload.mediaId;payload.clientMessageId=same?retry!.clientMessageId:crypto.randomUUID();retry=payload;sending.value=true;error.value='';try{const m=await conversationApi.send(id,payload);if(epoch!==generation)return;if(!messages.value.some(x=>x.id===m.id))messages.value.push(m);if(payload.contentType==='TEXT')draft.value='';else clearImage();retry=null;await bottom();await markRead();await store.refresh()}catch(e){if(epoch===generation)error.value=msg(e)+'；可点击发送重试'}finally{if(epoch===generation)sending.value=false}}
function clearImage(){if(image.value)URL.revokeObjectURL(image.value.url);image.value=null;if(fileInput.value)fileInput.value.value=''}
async function pickImage(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;if(file.size>5*1024*1024){ElMessage.warning('图片不能超过5MB');return}const epoch=generation;uploading.value=true;try{const asset=await mediaApi.upload(file,'PRIVATE');if(epoch===generation){clearImage();image.value={id:asset.id,url:URL.createObjectURL(file)}}}catch(e){if(epoch===generation)error.value=msg(e)}finally{if(epoch===generation)uploading.value=false}}
async function createGroup(){if(groupBusy.value)return;groupBusy.value=true;try{const c=await conversationApi.create(groupName.value);groupOpen.value=false;groupName.value='';await store.refresh();await router.push(`/chat/${c.id}`)}catch(e){ElMessage.error(msg(e))}finally{groupBusy.value=false}}
async function join(code=joinCode.value){if(groupBusy.value)return;groupBusy.value=true;try{const c=await conversationApi.join(code.trim());groupOpen.value=false;joinCode.value='';await store.refresh();await router.push(`/chat/${c.id}`)}catch(e){ElMessage.error(msg(e))}finally{groupBusy.value=false}}
async function details(){const id=activeId.value;if(!id)return;membersOpen.value=true;inviteKey=crypto.randomUUID();try{const [rows,first]=await Promise.all([conversationApi.members(id),socialApi.friends(1)]);if(id!==activeId.value)return;members.value=rows;const friends=[...first.items];let page=1;while(friends.length<first.total){const next=await socialApi.friends(++page);if(!next.items.length)break;friends.push(...next.items)}friendChoices.value=friends.filter(f=>!rows.some(m=>m.id===f.id))}catch(e){ElMessage.error(msg(e))}}
function resetInviteKey(){inviteKey=crypto.randomUUID()}
async function invite(){const id=activeId.value,target=inviteTarget.value;if(!id||!target||inviteBusy.value)return;inviteBusy.value=true;try{await conversationApi.invite(id,target,inviteKey);inviteKey=crypto.randomUUID();ElMessage.success('邀请已发送至好友私聊');inviteTarget.value=undefined;await store.refresh()}catch(e){ElMessage.error(msg(e))}finally{inviteBusy.value=false}}
async function rename(){if(!current.value)return;try{const result=await ElMessageBox.prompt('请输入新群名（最多40字）','修改群名',{inputValue:current.value.title,inputValidator:v=>!!v?.trim()&&[...v].length<=40||'请填写1至40字的群名'});current.value=await conversationApi.rename(current.value.id,result.value);await store.refresh()}catch(e){if(e instanceof Error)ElMessage.error(msg(e))}}
async function leave(){if(!current.value)return;try{await ElMessageBox.confirm('退出后无法读取群消息和图片；群主会移交给最早加入的成员，最后一人退出即解散。','退出群聊',{confirmButtonText:'退出',cancelButtonText:'取消'});await conversationApi.leave(current.value.id);membersOpen.value=false;await router.push('/chat');await store.refresh()}catch(e){if(e instanceof Error)ElMessage.error(msg(e))}}
function visible(){if(!document.hidden){void store.refresh();void loadLatest(false)}}
watch(activeId,()=>{generation++;requestSequence++;draft.value='';clearImage();retry=null;sending.value=false;uploading.value=false;olderLoading.value=false;membersOpen.value=false;messages.value=[];current.value=null;void loadLatest()}, {immediate:true})
onMounted(()=>{off=ws.subscribeWith('/user/queue/social',e=>{if(e.type==='CHAT_MESSAGE'){const m=e.data as ConversationMessage;if(m.conversationId===activeId.value){if(!messages.value.some(x=>x.id===m.id))messages.value.push(m);void bottom();void markRead()}}else if(e.type==='CONVERSATION_UPDATE'&&(e.data as {conversationId:number}).conversationId===activeId.value){void conversationApi.get(activeId.value!).then(c=>{if(c.id===activeId.value)current.value=c}).catch(()=>{current.value=null;messages.value=[];error.value='你已离开此会话'})}});offStatus=ws.onStatus((connected,reconnected)=>{if(connected&&reconnected)void loadLatest(false)});document.addEventListener('visibilitychange',visible)})
onBeforeUnmount(()=>{generation++;requestSequence++;off?.();offStatus?.();clearImage();document.removeEventListener('visibilitychange',visible)})
</script>

<template>
 <section class="social-chat" :class="{'has-thread':activeId}">
  <aside class="conversation-list">
   <div class="list-heading"><div><span class="eyebrow">和朋友聊一聊</span><h1>聊天 <small v-if="store.unread">{{store.unread}} 条未读</small></h1></div><el-button circle aria-label="创建或加入群聊" @click="groupOpen=true">＋</el-button></div>
   <div class="list-tools"><router-link to="/friends">好友管理 / 发起私聊</router-link><el-button text :loading="store.loading" @click="store.refresh">刷新</el-button></div>
   <el-alert v-if="store.error" :title="store.error" type="error" :closable="false" />
   <p v-if="!store.items.length&&!store.loading" class="empty">从好友页发起私聊，或创建一个群，约朋友一起开局。</p>
   <button v-for="c in store.items" :key="c.id" class="conversation-row" :class="{selected:c.id===activeId}" @click="router.push(`/chat/${c.id}`)">
    <el-avatar :size="44" :src="c.peer?.avatar">群</el-avatar><span class="conversation-summary"><strong>{{c.title}}</strong><span>{{preview(c)}}</span></span><span class="row-tail"><small>{{time(c.updatedAt)}}</small><b v-if="c.unreadCount">{{c.unreadCount>99?'99+':c.unreadCount}}</b></span>
   </button>
  </aside>
  <div class="thread">
   <div v-if="!activeId" class="thread-empty"><span>🌙</span><h2>让下一局，从聊天开始</h2><p>选择一个会话，分享日常、发送图片，或邀请朋友加入群聊。</p><el-button @click="groupOpen=true">创建或加入群聊</el-button></div>
   <template v-else>
    <header class="thread-heading"><el-button class="back" text @click="router.push('/chat')">‹ 返回</el-button><div><h2>{{current?.title||'加载会话…'}}</h2><p>{{current?.type==='GROUP'?`${current.memberCount} 人 · 群码 ${current.code}`:'好友私聊 · 支持文字、表情和图片'}}</p></div><el-button v-if="current?.type==='GROUP'" text @click="details">群资料</el-button></header>
    <el-alert v-if="error" :title="error" type="error" :closable="false" show-icon />
    <div ref="scroller" class="message-scroll" aria-live="polite" v-loading="loading">
     <div class="history-control"><el-button v-if="hasMore" text :loading="olderLoading" @click="older">加载更早的消息</el-button><small v-else>消息仅会话成员可见</small></div>
     <p v-if="current&&!messages.length&&!loading" class="empty">还没有消息，打个招呼吧 👋</p>
     <article v-for="m in messages" :key="m.id" class="message" :class="{mine:m.sender.id===auth.user?.id}">
      <el-avatar :size="34" :src="m.sender.avatar"/><div class="message-main"><div class="message-meta">{{m.sender.nickname}} <time>{{time(m.createdAt)}}</time></div><div class="bubble"><ProtectedImage v-if="m.contentType==='IMAGE'&&m.mediaId" :media-id="m.mediaId"/><div v-else-if="m.contentType==='GROUP_INVITE'" class="invite-card"><small>群聊邀请</small><strong>{{m.content}}</strong><span>群码 {{m.relatedCode}}</span><el-button size="small" :loading="groupBusy" @click="join(m.relatedCode!)">加入群聊</el-button></div><div v-else-if="m.contentType==='GAME_INVITE'" class="invite-card"><small>游戏房间邀请</small><strong>{{m.content}}</strong><span>房间码 {{m.relatedCode}}</span><el-button size="small" @click="router.push(`/join/${m.relatedCode}`)">查看并加入</el-button></div><span v-else>{{m.content}}</span></div></div>
     </article>
    </div>
    <div v-if="current" class="composer">
     <div class="composer-tools"><el-popover placement="top-start" width="240" trigger="click"><template #reference><el-button text aria-label="选择表情">☺ 表情</el-button></template><div class="emoji-grid"><button v-for="emoji in emojis" :key="emoji" @click="draft+=emoji">{{emoji}}</button></div></el-popover><el-button text :loading="uploading" :disabled="sending" @click="fileInput?.click()">▧ 图片</el-button><input ref="fileInput" type="file" accept="image/jpeg,image/png,image/webp" hidden @change="pickImage"/><small>Enter 发送 · Shift+Enter 换行</small></div>
     <div v-if="image" class="image-preview"><img :src="image.url" alt="待发送图片"/><el-button text :disabled="sending" @click="clearImage">移除图片</el-button><small>文字可在图片发送后单独发送</small></div>
     <el-input v-model="draft" type="textarea" :rows="3" :maxlength="4000" :disabled="sending" placeholder="说点什么…" resize="none" @keydown.enter.exact.prevent="send"/><div class="send-row"><small>{{[...draft].length}} / 2000</small><el-button type="primary" :loading="sending" :disabled="uploading||(!draft.trim()&&!image)" @click="send">发送</el-button></div>
    </div>
   </template>
  </div>
  <el-dialog v-model="groupOpen" title="创建或加入群聊" width="min(440px, 94vw)"><el-form label-position="top"><el-form-item label="创建新群（最多50人）"><el-input v-model="groupName" maxlength="40" placeholder="给你们的群起个名字"/><el-button class="dialog-action" type="primary" :loading="groupBusy" :disabled="!groupName.trim()" @click="createGroup">创建群聊</el-button></el-form-item><el-divider/><el-form-item label="凭8位群码加入"><el-input v-model="joinCode" maxlength="8" placeholder="输入朋友分享的群码"/><el-button class="dialog-action" :loading="groupBusy" :disabled="joinCode.trim().length!==8" @click="join()">加入群聊</el-button></el-form-item></el-form><p class="muted">群码请只分享给希望邀请的人。加入后可查看群内历史消息。</p></el-dialog>
  <el-dialog v-model="membersOpen" title="群资料" width="min(480px, 94vw)"><template v-if="current"><h3>{{current.title}}</h3><p>群码：<strong class="group-code">{{current.code}}</strong> · {{current.memberCount}} / 50 人</p><p class="muted">群码用于主动加入，邀请好友不会直接将对方拉入群。</p><div class="member-list"><span v-for="member in members" :key="member.id"><el-avatar :size="28" :src="member.avatar"/>{{member.nickname}}<small v-if="member.id===current.createdBy">群主</small></span></div><el-select v-model="inviteTarget" placeholder="选择要邀请的好友" @change="resetInviteKey"><el-option v-for="friend in friendChoices" :key="friend.id" :label="friend.nickname" :value="friend.id"/></el-select><el-button class="dialog-action" :disabled="!inviteTarget" :loading="inviteBusy" @click="invite">发送群邀请</el-button><div class="group-actions"><el-button v-if="current.createdBy===auth.user?.id" @click="rename">修改群名</el-button><el-button type="danger" plain @click="leave">退出群聊</el-button></div></template></el-dialog>
 </section>
</template>

<style scoped>
