-size:18px;margin:0;overflow-wrap:anywhere}.thread-heading p{font-size:12px;color:var(--ww-text-dim);margin:6px 0 0}.back{display:none}.message-scroll{flex:1;overflow-y:auto;padding:16px 24px;min-height:100px}.history-control{text-align:center;color:var(--ww-text-dim);margin-bottom:20px;font-size:12px}.message{display:flex;gap:10px;margin-bottom:24px;align-items:flex-start}.message.mine{flex-direction:row-reverse}.message-main{max-width:78%;min-width:0}.message-meta{color:var(--ww-text-dim);font-size:11px;margin:0 0 7px}.message-meta time{font-size:10px;margin-left:7px}.mine .message-meta{text-align:right}.bubble{padding:12px 15px;border-radius:0 14px 14px;background:#222d48;white-space:pre-wrap;overflow-wrap:anywhere;font-size:14px;line-height:1.65;width:fit-content}.mine .bubble{background:#4b376c;border-radius:14px 0 14px 14px;margin-left:auto}.invite-card{display:flex;flex-direction:column;gap:8px;min-width:160px}.invite-card small,.invite-card span{font-size:12px;color:var(--ww-text-dim)}.composer{border-top:1px solid var(--ww-border);padding:8px 20px 14px;background:rgba(9,13,27,.4)}.composer-tools{display:flex;align-items:center;gap:4px}.composer-tools small{margin-left:auto;font-size:10px;color:var(--ww-text-dim)}.send-row{display:flex;justify-content:space-between;align-items:center;margin-top:8px}.send-row small{color:var(--ww-text-dim);font-size:11px}.emoji-grid{display:grid;grid-template-columns:repeat(6,1fr);gap:6px}.emoji-grid button{border:0;background:transparent;font-size:24px;cursor:pointer}.image-preview{display:flex;align-items:center;gap:12px;margin:6px 0}.image-preview img{height:56px;max-width:80px;object-fit:contain;border-radius:8px}.image-preview small{font-size:10px;color:var(--ww-text-dim)}.dialog-action{margin-top:12px}.member-list{display:flex;gap:12px;flex-wrap:wrap;margin:20px 0}.member-list>span{display:flex;align-items:center;gap:6px;font-size:13px}.member-list small{color:var(--ww-moon)}.group-actions{display:flex;justify-content:space-between;margin-top:28px}.group-code{letter-spacing:2px;color:var(--ww-moon)}
@media(max-width:680px){.social-chat{display:block;height:calc(100dvh - 190px);min-height:400px;border-radius:14px;margin:4px auto 0}.conversation-list{height:100%;border:0}.thread{display:none;height:100%}.has-thread .conversation-list{display:none}.has-thread .thread{display:flex}.back{display:inline-flex}.thread-heading{padding:12px}.message-scroll{padding:12px}.message-main{max-width:80%}.composer{padding:6px 12px 10px}.composer-tools small{display:none}.thread-heading p{font-size:10px}.thread-heading h2{font-size:16px}.bubble{padding:10px 12px}.image-preview small{display:none}}
</style>
